package httpapi

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"testing"
	"time"

	"github.com/oklog/ulid/v2"

	"github.com/entirehq/entire-api/internal/authz"
	"github.com/entirehq/entire-api/internal/idtest"
	"github.com/entirehq/entire-api/internal/store"
)

// These are full-stack route tests for the trails surface (RFD-023 trails-native
// port, PR 1): a real chi+Huma router with the real gate middleware and a real
// Postgres-backed RepoStore, following the sessions_route_test.go /
// repos_meta_route_test.go conventions (newRepoAPIFixture, fakeAuthz, f.get).
// They need Postgres (ACTIVITY_TEST_DATABASE_URL) and skip without it.

// trailsFullName derives a per-run-unique "owner/repo" full name from the
// fixture's repoID (itself unique per run via uniqueSuffix). The trails routes
// resolve by full_name (not {repo_id}), and repos.full_name carries no
// uniqueness constraint + these route tests never truncate shared tables, so a
// fixed literal (e.g. "entirehq/entire.io") would collide across the several
// tests in this file — RepoIDByFullName's UNION ALL … LIMIT 1 would then
// nondeterministically resolve to whichever test's row Postgres returns first.
func trailsFullName(repoID string) string {
	return "entirehq/" + strings.ToLower(repoID)
}

// seedTrailsRepoEmpty names the fixture repo and enables its trails toggle,
// without inserting any repo_trails rows — the shared setup for tests that
// need a trails-enabled repo with zero trails (e.g. pinning the empty-array
// wire shape). seedTrailsRepo layers the trail inserts on top of this.
func seedTrailsRepoEmpty(t *testing.T, repo *store.RepoStore, repoID, fullName string) {
	t.Helper()
	ctx := context.Background()
	rid := ulid.MustParse(repoID)
	if _, err := repo.Pool().Exec(ctx,
		`UPDATE repos SET full_name = $1 WHERE id = $2`, fullName, rid[:]); err != nil {
		t.Fatalf("set full_name: %v", err)
	}
	if _, err := repo.Pool().Exec(ctx,
		`INSERT INTO repo_setting_kv (repo_id, setting_key, value) VALUES ($1, 'trails', true)
		 ON CONFLICT (repo_id, setting_key) DO UPDATE SET value = true`, rid[:]); err != nil {
		t.Fatalf("enable trails: %v", err)
	}
}

// seedTrailsRepo names the fixture repo, enables its trails toggle, and inserts
// two trails directly on the store's pool — there is no store write method for
// repo_trails yet (Task 1/2 only added reads), so the seed goes straight to SQL,
// same as the other route-test seeds that predate their store method (e.g.
// seedRouteSessionCore's raw checkpoint_commits inserts).
func seedTrailsRepo(t *testing.T, repo *store.RepoStore, repoID, fullName string) {
	t.Helper()
	ctx := context.Background()
	rid := ulid.MustParse(repoID)
	seedTrailsRepoEmpty(t, repo, repoID, fullName)
	now := time.Now().UTC()
	// repo_trails.id is a global PK (not scoped per repo_id), so the seeded
	// trail/author ids must be unique per test run too — derive them from repoID
	// (itself unique per run, see uniqueSuffix) rather than a fixed label.
	author := ulid.MustParse(idtest.ULID("trail-author-" + repoID))
	trail1 := ulid.MustParse(idtest.ULID("route-trail-1-" + repoID))
	trail2 := ulid.MustParse(idtest.ULID("route-trail-2-" + repoID))
	for _, tr := range []struct {
		id     ulid.ULID
		number int
		title  string
		status string
		branch any // string or nil
		upd    time.Time
	}{
		{trail1, 1, "First trail", "open", "feat/one", now.Add(-time.Hour)},
		{trail2, 2, "Second trail", "merged", nil, now},
	} {
		if _, err := repo.Pool().Exec(ctx, `
			INSERT INTO repo_trails (id, repo_id, number, title, status, branch, base, type,
				author_account_id, has_code_changes, created_at, updated_at)
			VALUES ($1,$2,$3,$4,$5,$6,'main','standard',$7,true,$8,$8)`,
			tr.id[:], rid[:], tr.number, tr.title, tr.status, tr.branch, author[:], tr.upd); err != nil {
			t.Fatalf("insert trail %s: %v", tr.title, err)
		}
	}
}

func TestIntegrationTrailsListRoute(t *testing.T) {
	f, repo, repoID, _ := newRepoAPIFixture(t, true, false)
	f.deps.Reader = authz.NewReaderFromClient(&fakeAuthz{repos: map[string]bool{repoID: true}})
	fullName := trailsFullName(repoID)
	seedTrailsRepo(t, repo, repoID, fullName)

	var out struct {
		Items         []map[string]any `json:"items"`
		NextPageToken *string          `json:"nextPageToken"`
	}
	if got := f.get(t, "/api/v1/trails/gh/"+fullName, true, &out); got != http.StatusOK {
		t.Fatalf("list: got %d, want 200", got)
	}
	if len(out.Items) != 2 {
		t.Fatalf("items = %d, want 2", len(out.Items))
	}
	if out.NextPageToken != nil {
		t.Errorf("nextPageToken = %v, want nil (only page)", *out.NextPageToken)
	}
	// updated_at DESC: trail-2 first.
	if out.Items[0]["title"] != "Second trail" || out.Items[1]["title"] != "First trail" {
		t.Errorf("order: %v, %v", out.Items[0]["title"], out.Items[1]["title"])
	}
	if out.Items[1]["phase"] != "building" { // open + has_code_changes, no reviewers
		t.Errorf("phase = %v, want building", out.Items[1]["phase"])
	}
	if out.Items[0]["branch"] != nil {
		t.Errorf("null branch must serialize as null, got %v", out.Items[0]["branch"])
	}
	author := out.Items[0]["author"].(map[string]any)
	if author["id"] != idtest.ULID("trail-author-"+repoID) {
		t.Errorf("author.id = %v (ULID text expected)", author["id"])
	}
}

