38	// MeTrailsInput is the query for GET /me/trails.
39	type MeTrailsInput struct {
40		Status string   `query:"status" doc:"Comma-separated statuses; omit for all"`
41		Author string   `query:"author" doc:"'me' filters to the caller's own trails"`
